}
function drawBeam(e){
  const top=e.y+8, hw=beamHalfWidth(e,H);
  ctx.save();
  ctx.globalAlpha=0.30; ctx.fillStyle='#4060ff';
  ctx.beginPath(); ctx.moveTo(e.x-2,top); ctx.lineTo(e.x+2,top);
  ctx.lineTo(e.x+hw,H); ctx.lineTo(e.x-hw,H); ctx.closePath(); ctx.fill();
  ctx.globalAlpha=0.55; ctx.fillStyle='#80a0ff';
  for(let y=top+((frameN*2)%8); y<H; y+=8){
