    ctx.fillRect(e.x-w, y, w*2, 2);
  }
  ctx.restore();
}
function drawExplosions(){
  for(const x of explosions){
    const p=x.t, col=x.player?'#ffffff':(x.color||'#ffe600');
    ctx.save(); ctx.translate(x.x,x.y); ctx.strokeStyle=col; ctx.fillStyle=col;
    if(x.player){
      ctx.lineWidth=1;
      for(let i=0;i<6;i++){
        const a=i*1.05+p*0.15, r=3+p*0.9;
        ctx.beginPath(); ctx.moveTo(Math.cos(a)*r*0.4,Math.sin(a)*r*0.4);
        ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r); ctx.stroke();
      }
      if(p>8){ ctx.globalAlpha=1-(p-8)/18;
        for(let i=0;i<8;i++){ const a=i*0.785, r=6+p*0.8; ctx.fillRect(Math.cos(a)*r|0,Math.sin(a)*r|0,2,2); } }
    } else {
      ctx.lineWidth=1; const r=2+p*0.7;
      for(let i=0;i<8;i++){ const a=i*0.785+p*0.1;
        ctx.beginPath(); ctx.moveTo(Math.cos(a)*(r*0.35),Math.sin(a)*(r*0.35));
        ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r); ctx.stroke(); }
      if(p>10){ ctx.globalAlpha=1-(p-10)/10;
        for(let i=0;i<4;i++){ const a=i*1.57+p*0.3; ctx.fillRect(Math.cos(a)*r|0,Math.sin(a)*r|0,2,2); } }
    }
    ctx.restore();
  }
  ctx.globalAlpha=1;
}
function drawPlayer(){
  if(!player.alive) return;
